DROP TABLE IF EXISTS `items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `items` (
  `item_id` int unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int unsigned NOT NULL,
  `item_code` varchar(50) NOT NULL,
  `item_name` varchar(160) NOT NULL,
  `tax_code_id` int unsigned NOT NULL,
  `unit_of_measure` varchar(20) NOT NULL DEFAULT 'Each',
  `active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`item_id`),
  UNIQUE KEY `uq_items_company_item` (`company_id`,`item_id`),
  UNIQUE KEY `uq_items_company_code` (`company_id`,`item_code`),
  KEY `idx_items_tax_code` (`tax_code_id`),
  CONSTRAINT `fk_items_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`company_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_items_tax_code` FOREIGN KEY (`tax_code_id`) REFERENCES `tax_codes` (`tax_code_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
