--
-- Table structure for table `transactions`
--

DROP TABLE IF EXISTS `transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transactions` (
  `transaction_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int unsigned NOT NULL,
  `customer_id` int unsigned NOT NULL,
  `transaction_code` varchar(60) NOT NULL,
  `transaction_date` date NOT NULL,
  `transaction_type` varchar(30) NOT NULL DEFAULT 'SalesInvoice',
  `status` varchar(20) NOT NULL DEFAULT 'Committed',
  `currency_code` char(3) NOT NULL DEFAULT 'USD',
  `total_amount` decimal(15,2) NOT NULL,
  `total_tax` decimal(15,2) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`transaction_id`),
  UNIQUE KEY `uq_transactions_company_id` (`company_id`,`transaction_id`),
  UNIQUE KEY `uq_transactions_company_code` (`company_id`,`transaction_code`),
  KEY `fk_transactions_customer_same_company` (`company_id`,`customer_id`),
  KEY `idx_transactions_date_status` (`transaction_date`,`status`),
  KEY `idx_transactions_customer_date` (`customer_id`,`transaction_date`),
  CONSTRAINT `fk_transactions_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`company_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_transactions_customer_same_company` FOREIGN KEY (`company_id`, `customer_id`) REFERENCES `customers` (`company_id`, `customer_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_transactions_amounts` CHECK (((`total_amount` >= 0) and (`total_tax` >= 0))),
  CONSTRAINT `chk_transactions_status` CHECK ((`status` in (_utf8mb4'Committed',_utf8mb4'Posted',_utf8mb4'Voided')))
) ENGINE=InnoDB AUTO_INCREMENT=2001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

